const listWorkoutExercises = `-- name: ListWorkoutExercises :many
select we.workout_id, we.position, we.exercise_id, we.group_name, we.sets, we.reps, we.hold_seconds, we.weight_value, we.weight_unit, we.rest_seconds, we.tempo, we.target_effort, we.notes, we.group_kind, e.name as exercise_name, e.equipment::text[] as exercise_equipment, e.each_side as exercise_each_side,
  e.garmin_exercise as exercise_garmin_exercise
from workout_exercises we
join workouts w on w.id = we.workout_id
join training_plans p on p.id = w.plan_id
join exercises e on e.id = we.exercise_id
where p.user_id = $1::uuid
  and ($2::uuid is null or w.plan_id = $2::uuid)
  and ($3::uuid[] is null or w.id = any($3::uuid[]))
  and ($4::date is null or w.date >= $4::date)
  and ($5::date is null or w.date <= $5::date)
order by we.workout_id, we.position
`

type ListWorkoutExercisesParams struct {
	UserID     pgtype.UUID
	PlanID     pgtype.UUID
	WorkoutIds []pgtype.UUID
	StartDate  pgtype.Date
	EndDate    pgtype.Date
}

type ListWorkoutExercisesRow struct {
	WorkoutID              pgtype.UUID
	Position               int32
	ExerciseID             pgtype.UUID
	GroupName              string
	Sets                   int32
	Reps                   int32
	HoldSeconds            int32
	WeightValue            float64
	WeightUnit             NullWeightUnit
	RestSeconds            int32
	Tempo                  string
	TargetEffort           int32
	Notes                  string
	GroupKind              string
	ExerciseName           string
	ExerciseEquipment      []string
	ExerciseEachSide       bool
	ExerciseGarminExercise string
}

// Lists the exercises of the user's workouts, optionally of a plan, of
// some workouts or within dates, by workout and position.
func (q *Queries) ListWorkoutExercises(ctx context.Context, arg *ListWorkoutExercisesParams) ([]*ListWorkoutExercisesRow, error) {
	rows, err := q.db.Query(ctx, listWorkoutExercises,
		arg.UserID,
		arg.PlanID,
		arg.WorkoutIds,
		arg.StartDate,
		arg.EndDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListWorkoutExercisesRow
	for rows.Next() {
		var i ListWorkoutExercisesRow
		if err := rows.Scan(
			&i.WorkoutID,
			&i.Position,
			&i.ExerciseID,
			&i.GroupName,
			&i.Sets,
			&i.Reps,
			&i.HoldSeconds,
			&i.WeightValue,
			&i.WeightUnit,
			&i.RestSeconds,
			&i.Tempo,
			&i.TargetEffort,
			&i.Notes,
			&i.GroupKind,
			&i.ExerciseName,
			&i.ExerciseEquipment,
			&i.ExerciseEachSide,
			&i.ExerciseGarminExercise,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setHomeEquipment = `-- name: SetHomeEquipment :one
insert into home_equipment (user_id, equipment)
values ($1, $2)
on conflict (user_id) do update set
  equipment = excluded.equipment,
  update_time = now()
returning user_id, equipment, update_time
`

type SetHomeEquipmentParams struct {
	UserID    pgtype.UUID
	Equipment json.RawMessage
}

func (q *Queries) SetHomeEquipment(ctx context.Context, arg *SetHomeEquipmentParams) (*HomeEquipment, error) {
	row := q.db.QueryRow(ctx, setHomeEquipment, arg.UserID, arg.Equipment)
	var i HomeEquipment
	err := row.Scan(&i.UserID, &i.Equipment, &i.UpdateTime)
	return &i, err
}

const updateExercise = `-- name: UpdateExercise :one
update exercises set
  name = $3,
  instructions = $4,
  feel = $5,
  primary_muscles = $10::text[]::muscle[],
  secondary_muscles = $11::text[]::muscle[],
  equipment = $12::text[]::equipment[],
  equipment_notes = $6,
  each_side = $7,
  animations = $8,
  garmin_exercise = $9,
  update_time = now()
where id = $1 and user_id = $2
returning id, user_id, name, instructions, feel, primary_muscles, secondary_muscles, equipment, equipment_notes, each_side, animations, create_time, update_time, garmin_exercise
`

type UpdateExerciseParams struct {
	ID               pgtype.UUID
	UserID           pgtype.UUID
	Name             string
	Instructions     []string
	Feel             string
	EquipmentNotes   string
	EachSide         bool
	Animations       json.RawMessage
	GarminExercise   string
	PrimaryMuscles   []string
	SecondaryMuscles []string
	Equipment        []string
}

func (q *Queries) UpdateExercise(ctx context.Context, arg *UpdateExerciseParams) (*Exercise, error) {
	row := q.db.QueryRow(ctx, updateExercise,
		arg.ID,
		arg.UserID,
		arg.Name,
		arg.Instructions,
		arg.Feel,
		arg.EquipmentNotes,
		arg.EachSide,
		arg.Animations,
		arg.GarminExercise,
		arg.PrimaryMuscles,
		arg.SecondaryMuscles,
		arg.Equipment,
	)
	var i Exercise
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Name,
		&i.Instructions,
		&i.Feel,
		&i.PrimaryMuscles,
		&i.SecondaryMuscles,
		&i.Equipment,
		&i.EquipmentNotes,
		&i.EachSide,
		&i.Animations,
		&i.CreateTime,
		&i.UpdateTime,
		&i.GarminExercise,
	)
	return &i, err
}

const upsertStrengthLog = `-- name: UpsertStrengthLog :one
insert into strength_logs (
  user_id,
  workout_id,
  date,
  effort,
  notes
) values (
  $1, $2, $3, $4, $5
)
on conflict (workout_id) do update set
  date = excluded.date,
  effort = excluded.effort,
  notes = excluded.notes,
  update_time = now()
returning id, user_id, workout_id, date, effort, notes, complete_time, update_time
`

type UpsertStrengthLogParams struct {
	UserID    pgtype.UUID
	WorkoutID pgtype.UUID
	Date      pgtype.Date
	Effort    NullSessionEffort
	Notes     string
}

func (q *Queries) UpsertStrengthLog(ctx context.Context, arg *UpsertStrengthLogParams) (*StrengthLog, error) {
	row := q.db.QueryRow(ctx, upsertStrengthLog,
		arg.UserID,
		arg.WorkoutID,
		arg.Date,
		arg.Effort,
		arg.Notes,
	)
	var i StrengthLog
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.WorkoutID,
		&i.Date,
		&i.Effort,
		&i.Notes,
		&i.CompleteTime,
		&i.UpdateTime,
	)
	return &i, err
}
